const b = $json.body ?? $json;
for (const key of ['check_in','check_out','adults']) { if (b[key] === undefined || b[key] === null || String(b[key]).trim() === '') throw new Error(`Missing required field: ${key}`); }
const adults = Number(b.adults); const children = Number(b.children || 0);
if (!Number.isInteger(adults) || adults < 1) throw new Error('adults must be a positive integer');
if (!Number.isInteger(children) || children < 0) throw new Error('children must be a nonnegative integer');
return [{ json: { check_in: String(b.check_in), check_out: String(b.check_out), adults, children, room_type_code: b.room_type_code ? String(b.room_type_code) : null } }];

const facts = $('Get Hotel Facts').item.json;
const availability = $('Check Availability').item.json;
const sellable = (availability.results || []).filter(x => x.pricing?.sellable === true && Number.isFinite(x.pricing?.total_kgs));
return [{ json: { ok: true, hotel_facts: facts, search: { check_in: availability.check_in, check_out: availability.check_out, nights: availability.nights, adults: availability.adults, children: availability.children }, sellable_options: sellable, truth_rules: ['Use only sellable_options for date-specific offers.', 'ReservationRequest is not a reservation.', 'Do not invent policy fields marked PARTIAL, UNKNOWN or STALE_DO_NOT_USE.', 'Provider/channel delivery is handled outside Resort Core.'] } }];
